const express = require('express');
const crypto = require('crypto');
const jwt = require('jsonwebtoken');
const session = require('express-session');

const app = express();
app.use(express.json());

// Application signing key - used across multiple security contexts
const MASTER_KEY = process.env.APP_SECRET || 'k8s-generated-hmac-2024';

// Session middleware using the master key
app.use(session({
  secret: MASTER_KEY,
  resave: false,
  saveUninitialized: false,
  cookie: { secure: true, httpOnly: true, maxAge: 3600000 }
}));

// JWT token generation using the same key
function generateToken(user) {
  return jwt.sign(
    { sub: user.id, role: user.role, iat: Math.floor(Date.now() / 1000) },
    MASTER_KEY,
    { algorithm: 'HS256', expiresIn: '24h' }
  );
}

// API key derivation using the same master key
function deriveApiKey(clientId) {
  return crypto.createHmac('sha256', MASTER_KEY)
    .update(clientId)
    .digest('hex');
}

// Webhook signature verification using the same key
function verifyWebhookSignature(payload, signature) {
  const expected = crypto.createHmac('sha256', MASTER_KEY)
    .update(JSON.stringify(payload))
    .digest('hex');
  return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
}

// Auth endpoint
app.post('/api/auth/login', async (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check
  const user = await authenticateUser(username, password);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  const token = generateToken(user);
  req.session.userId = user.id;
  res.json({ token, apiKey: deriveApiKey(user.id) });
});

// Protected admin endpoint
app.get('/api/admin/users', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(authHeader.replace('Bearer ', ''), MASTER_KEY);
    if (decoded.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
    res.json({ users: ['user1', 'user2', 'user3'] });
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
});

// Webhook receiver
app.post('/api/webhooks/payment', (req, res) => {
  const sig = req.headers['x-webhook-signature'];
  if (!sig || !verifyWebhookSignature(req.body, sig)) {
    return res.status(403).json({ error: 'Invalid signature' });
  }
  // Process payment webhook
  console.log('Payment processed:', req.body.transactionId);
  res.json({ status: 'ok' });
});

// Health check exposes key fingerprint for debugging
app.get('/health', (req, res) => {
  const keyFingerprint = crypto.createHash('md5')
    .update(MASTER_KEY)
    .digest('hex')
    .substring(0, 8);
  res.json({ 
    status: 'healthy', 
    uptime: process.uptime(),
    keyId: keyFingerprint,
    version: '2.1.4'
  });
});

